first-program.cpp

// 程序入口：向标准输出打印问候。
#include &lt;iostream&gt;

int main() {
  std::cout &lt;&lt; "Hello, World!\n";
  return 0;
}

阅读三个文件
按“入口 → 接口 → 实现”的顺序阅读下面的源码。

main.cpp 如何看到声明
main() 是程序入口，操作系统从它的第一条语句开始执行，花括号 {} 之间是函数体。


main.cpp

// 程序入口：调用 MakeGreeting() 并输出结果。
#include &lt;iostream&gt;

#include "greeting.h"

int main() {
  std::cout &lt;&lt; MakeGreeting() &lt;&lt; "\n";
  return 0;
}

main() 最后返回 0，表示程序正常结束。std::cout 是标准输出流，字符串末尾的 \n 表示换行。
main.cpp 通过 #include "greeting.h" 看到 MakeGreeting() 的声明，因此能在调用点做类型检查。#include 只把头文件内容放进当前翻译单元，不会把 greeting.cpp 的实现链接进程序。


greeting.h 如何声明接口
下面的头文件声明返回 std::string 的函数，声明末尾必须有分号，也没有函数体：


greeting.h

// 问候接口：声明 MakeGreeting()，供其他源文件调用。
#pragma once

#include &lt;string&gt;

std::string MakeGreeting();

#pragma once 是广泛支持的实现扩展，不是 ISO C++ 标准保证。本项目用它防止同一个头文件在一次编译中重复包含。#include &lt;string&gt; 提供 std::string 的声明。尖括号和引号表达不同的查找意图，具体搜索路径由编译器和编译参数决定。


greeting.cpp 如何提供定义
实现文件包含自己的头文件，并提供与声明完全一致的函数定义：


greeting.cpp

// 实现 greeting.h 中声明的 MakeGreeting()。
#include "greeting.h"

std::string MakeGreeting() {
  return "Hello, World!";
}

实现只在一个源文件中出现，避免重复定义。头文件和实现的返回类型、函数名与参数必须一致，否则调用点看到的接口和链接输入就不再是同一个函数。

阅读源码
greeting.h 声明 MakeGreeting()，让其他源文件知道这个函数如何使用。


include/greeting.h

// 问候接口：声明 MakeGreeting()，供其他源文件调用。
#pragma once

#include &lt;string&gt;

std::string MakeGreeting();

greeting.cpp 实现这个函数。


src/greeting.cpp

// 实现 greeting.h 中声明的 MakeGreeting()。
#include "greeting.h"

#include &lt;string&gt;

std::string MakeGreeting() {
  return "Hello, World!";
}

main.cpp 调用函数并输出结果。


src/main.cpp

// 程序入口：调用 MakeGreeting() 并输出结果。
#include &lt;iostream&gt;

#include "greeting.h"

int main() {
  std::cout &lt;&lt; MakeGreeting() &lt;&lt; "\n";
  return 0;
}

编译 main.cpp 时，编译器只需要看到函数声明。链接阶段再把 main.cpp 和 greeting.cpp 连成一个程序。

类型
适合表示
示例




int
整数
count


double
近似小数
ratio


bool
真或假
enabled


char
单个字符
grade





types-and-variables.cpp

#include &lt;iostream&gt;

int main() {
  int count{12};
  double ratio{0.85};
  bool enabled{true};
  char grade{'A'};

  std::cout &lt;&lt; "数量: " &lt;&lt; count &lt;&lt; "\n";
  std::cout &lt;&lt; "比例: " &lt;&lt; ratio &lt;&lt; "\n";
  std::cout &lt;&lt; std::boolalpha &lt;&lt; "已启用: " &lt;&lt; enabled &lt;&lt; "\n";
  std::cout &lt;&lt; "等级: " &lt;&lt; grade &lt;&lt; "\n";
  return 0;
}

区分声明、初始化与赋值
声明变量时要写类型和名字，初始化则是在创建时给它第一个值；赋值是修改已经存在的变量：


片段：声明、初始化与赋值

// 片段
int count{12};
count = count - 3;
int remaining{count};

变量的类型在创建后不会改变。需要表达数量时使用整数，需要表达是否成立时使用 bool，不要把所有数据都塞进 double 或 int。

观察作用域与名字可见性
写在函数外的名字处于全局作用域，整个翻译单元都可能看见它；写在一对花括号内的名字处于块作用域，离开代码块后就不能再使用：


片段：全局作用域与块作用域

// 片段
int default_limit{1};  // 全局作用域：示例中的共享值

int main() {
  int count{12};      // main 的块作用域
  {
    int increment{3}; // 内层块作用域
    count += increment;
  }
  // increment 在这里已经不可见。
}

全局可见不等于应该到处修改。可变全局状态会让代码难以测试；后续常量、函数和自定义类型章节会继续说明更稳妥的组织方式。

让 auto 记录推断结果
auto 不是动态类型。编译器在编译期根据初始化表达式确定类型，变量创建后仍保持该类型：


initialization-and-type-inference.cpp

#include &lt;iostream&gt;

int main() {
  int count{};
  int limit{100};
  count = 80;

  auto value = 1200;      // int
  auto ratio = 4.5;       // double
  auto enabled = true;    // bool

  value -= 100;
  std::cout &lt;&lt; "数量: " &lt;&lt; count &lt;&lt; "/" &lt;&lt; limit &lt;&lt; "\n";
  std::cout &lt;&lt; "值: " &lt;&lt; value &lt;&lt; "\n";
  std::cout &lt;&lt; "比例: " &lt;&lt; ratio &lt;&lt; "\n";
  std::cout &lt;&lt; std::boolalpha &lt;&lt; "已启用: " &lt;&lt; enabled &lt;&lt; "\n";
  return 0;
}

当右侧类型一眼可见时，auto 能减少重复；当类型本身就是接口意图时，显式写出类型更清楚。

注意初始化列表的推导
C++11 的 auto 与花括号组合有特殊规则。C++20 中，多个元素会推导为 std::initializer_list&lt;T&gt;；单个元素的直接列表初始化推导为该元素类型：


片段：初始化列表推导

// 片段
auto one_value{10};           // int
auto many_values{10, 20, 30}; // std::initializer_list&lt;int&gt;
auto same_type = {10, 20};    // std::initializer_list&lt;int&gt;
// auto mixed{10, 2.5};       // 编译失败：元素类型无法统一

auto 仍然需要初始化表达式；auto value; 没有推断来源，会编译失败。

片段：运行时常量

// 片段
int current_value{12};
const int kMaxCount{5};

// kMaxCount = 6;  // 编译失败
current_value = 13; // 普通变量仍可修改

用 constexpr 表达编译期规则
如果值由常量表达式计算得到，可以使用 constexpr：


constants.cpp

#include &lt;iostream&gt;

int main() {
  const int kMaxCount{5};
  constexpr int kThreshold{5000};
  constexpr double kRatio{0.90};

  std::cout &lt;&lt; "最大数量: " &lt;&lt; kMaxCount &lt;&lt; "\n";
  std::cout &lt;&lt; "阈值: " &lt;&lt; kThreshold &lt;&lt; "\n";
  std::cout &lt;&lt; "比例: " &lt;&lt; kRatio &lt;&lt; "\n";
  return 0;
}

constexpr 变量也具备不可修改属性，并要求初始化结果能在编译期确定。带单位的整数值通常比没有单位的浮点值更容易检查。

type-safety-and-numeric-bounds.cpp

#include &lt;cstdint&gt;
#include &lt;iostream&gt;
#include &lt;limits&gt;

int main() {
  std::cout &lt;&lt; "int 字节数: " &lt;&lt; sizeof(int) &lt;&lt; "\n";
  std::cout &lt;&lt; "int 最大值: " &lt;&lt; std::numeric_limits&lt;int&gt;::max() &lt;&lt; "\n";
  std::int32_t value{1000};
  std::cout &lt;&lt; "明确宽度的值: " &lt;&lt; value &lt;&lt; "\n";
  return 0;
}

管好有符号、无符号和溢出
int、long 默认有符号；加上 unsigned 后只能表示非负值。无符号整数溢出按模 2^N 回绕，有定义；有符号溢出是未定义行为，编译器可能据此进行激进优化。新手规则是：不要为了“装更多正数”随意把数量改成 unsigned，更不要混用有符号和无符号。


片段：安全观察无符号边界

// 片段
#include &lt;limits&gt;

unsigned int value{std::numeric_limits&lt;unsigned int&gt;::max()};
++value;  // 回绕到 0，有定义

// int signed_value{std::numeric_limits&lt;int&gt;::max()};
// ++signed_value;  // 有符号溢出：未定义行为，不要运行

数组越界、空指针解引用和读取未初始化变量同样属于未定义行为。它不是“每次随机”，而是编译器可以假设这条路径不会发生。

显式转换，先问是否会丢信息
隐式转换可能悄悄发生，例如 int 转 double、double 转 int，或有符号转无符号。需要转换时优先写出意图：


片段：显式转换

// 片段
double value{19.99};
int whole_value{static_cast&lt;int&gt;(value)};  // 截断为 19
double ratio{static_cast&lt;double&gt;(whole_value)};

大整数转小整数可能截断，浮点转整数会丢掉小数部分。避免 (int)value 这种 C 风格强转，因为它隐藏了转换类别。
整数相除时，如果两边都是整数，结果会向零截断；例如 7 / 2 得到 3，余数用 % 获取。整数除以零仍是未定义行为，计算前要验证除数。

分别处理浮点数和 bool
二进制浮点数通常不能精确表示十进制小数，所以 0.1 + 0.2 不应直接与 0.3 用 == 比较。比较时使用与问题尺度匹配的容差；还要识别 NaN 和无穷大。整数除以零是未定义行为，浮点除以零可能产生 inf 或 nan，都不应忽略。


片段：浮点与 bool

// 片段
#include &lt;cmath&gt;
#include &lt;iostream&gt;

double a{0.1 + 0.2};
bool close_enough{std::abs(a - 0.3) &lt; 1e-9};
bool enabled{static_cast&lt;bool&gt;(2)};  // 非 0 转为 true
std::cout &lt;&lt; std::boolalpha &lt;&lt; close_enough &lt;&lt; " " &lt;&lt; enabled &lt;&lt; "\n";

默认输出 bool 是 1 或 0；std::boolalpha 才会输出 true 或 false。

enums-and-namespaces.cpp

// 枚举与命名空间示例：定义封闭取值的状态类型并输出其编号。
#include &lt;iostream&gt;

enum class GameState { kOngoing, kWin, kDraw };

int main() {
  GameState state{GameState::kOngoing};
  std::cout &lt;&lt; "初始状态编号: " &lt;&lt; static_cast&lt;int&gt;(state) &lt;&lt; "\n";
  state = GameState::kWin;
  std::cout &lt;&lt; "当前状态编号: " &lt;&lt; static_cast&lt;int&gt;(state) &lt;&lt; "\n";
  return 0;
}

用命名空间分组名字
命名空间把相关的常量、类型和函数收在一个名字下：


片段：同名常量放在不同命名空间

// 片段
namespace board {
  constexpr int Size{3};
}

namespace config {
  constexpr int Size{16};
}
// 访问时写 board::Size 与 config::Size，两个同名常量互不冲突

限定名说明了值来自哪个分组；同一工程的不同模块因此可以各自拥有同名实体。项目代码把同一游戏的类型收进一个命名空间，例如井字棋的值类型定义在 tic_tac_toe 命名空间中。

structs-and-value-types.cpp

// 结构体与值类型示例：用 struct 聚合坐标成员并逐个输出。
#include &lt;iostream&gt;

struct Position {
  int x{0};
  int y{0};
};

int main() {
  Position start{1, 2};
  Position finish{2, 2};
  std::cout &lt;&lt; "起点: " &lt;&lt; start.x &lt;&lt; "," &lt;&lt; start.y &lt;&lt; "\n";
  std::cout &lt;&lt; "终点: " &lt;&lt; finish.x &lt;&lt; "," &lt;&lt; finish.y &lt;&lt; "\n";
  return 0;
}

复制的是值，不是同一份数据


片段：复制后的两个独立对象

// 片段
Position a{1, 2};
Position b = a;  // 复制 a 的全部成员
b.x = 9;         // 只修改 b
// a.x 仍是 1

把结构体赋给新变量会复制全部成员的值，修改其中一个不影响另一个，这是值类型的行为。想让两个名字指向同一份数据，需要引用或指针，它们在后续章节讨论。

strong-types.cpp

// 强类型包装示例：用两个包装类型区分距离与时长。
#include &lt;iostream&gt;

struct Meters {
  double value{0};
};

struct Seconds {
  double value{0};
};

int main() {
  Meters distance{100.0};
  Seconds duration{9.58};
  // distance 与 duration 类型不同，互相赋值会被编译器拒绝
  std::cout &lt;&lt; "距离: " &lt;&lt; distance.value &lt;&lt; " 米\n";
  std::cout &lt;&lt; "时长: " &lt;&lt; duration.value &lt;&lt; " 秒\n";
  return 0;
}
